on conflict(type) do update set display_name=excluded.display_name,category=excluded.category,placement_radius=excluded.placement_radius,risk_weight=excluded.risk_weight,sort_order=excluded.sort_order;

on conflict(id) do update set label=excluded.label,min_x=excluded.min_x,max_x=excluded.max_x,min_z=excluded.min_z,max_z=excluded.max_z,ground_y=excluded.ground_y,max_occupants=excluded.max_occupants,allowed_types=excluded.allowed_types;
